void Infusion_Task_Pedal_Deal(uint16_t _code,uint32_t _data)
{
    // uint32_t _cmd = ramcof._suctioncof._pedalcof;      //获取踏板的配置 1 3 5
    uint32_t _cmd = _infcof->_pedalcof;      //获取踏板的配置 1 3 5
    uint16_t _duty = (uint16_t) _data;       //获取占空比;
    _code = BSWAP_16(_code);
    if(_code>FOOTBOARD_SWITCH)  //开关占空比混合
    {
        _code -= FOOTBOARD_SWITCH;
    }
    if(_cmd>0&&_cmd<FOOTBOARD_SWITCH && ramdata._cassette_state._state == CASSETTE_LOAD)   //踏板形成控制
    {
        switch (_cmd)
        {
            case FOOTBOARD_LINE_ONE:   //响应踏板第一阶段
            case FOOTBOARD_LINE_SECOND: //响应踏板第二阶段
            case FOOTBOARD_LINE_THIRD:
            {
                if(_code == _cmd)   //参数匹配
                {
                    _duty = _data;
                }
            }
            break;
            default:
                break;
        }
        if(_code == FOOTBOARD_ZERO) //踏板回到零点
            _duty = 0;
        if(_code>_cmd && _code < FOOTBOARD_SWITCH)   //超过所设置的段就最大输出
            _duty = 100;
        if (_duty > 0) 
        {
            Infusion_Task_ValveCtl(1);
            ramdata._cassette_state._pen_is_press_1 = 1; 
        }
        else
        {
            Infusion_Task_ValveCtl(0);
            ramdata._cassette_state._pen_is_press_1 = 0;
        }
    }
}


void Infusion_Task_ValveCtl(uint8_t _en)
{
    if (_en)
    {
        bsp_valve_Ctl(VALVE_INFUSION,  1);  //打开灌注
    }
    else
    {
        if(_infcof->_enable != 1)
            bsp_valve_Ctl(VALVE_INFUSION,  0);  //关闭灌注
    }
    
}
int  Infusion_Task_Init()
{
    Infusion_ctor();
    Normal_Task_RegisterFun(Infusion_Task_Cmd);
	Pedal_Task_RegisterFun(Infusion_Task_Pedal_Deal);
    QActive_setAttr(AO_Infusion,THREAD_NAME_ATTR,"Inf_mqm");
    QACTIVE_START(AO_Infusion,QPC_INFUSION_PRO,Infusion_queueSto,Q_DIM(Infusion_queueSto),Infusion_task_stack,INFUSION_TASK_SIZE,NULL);
}
INIT_APP_EXPORT(Infusion_Task_Init);



